/**
 * MySQL Backup Pro - Admin JS
 * AMD module for Moodle 4.1+
 *
 * @package    local_mysqlbackuppro
 * @copyright  2024 Louis Jhosimar Ocampo | GestLife Dev
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_mysqlbackuppro/admin', ['jquery', 'core/str', 'core/notification'], function($, Str, Notification) {

    // S3 Explorer state.
    var s3State = {
        prefix: '',
        page: 1,
        per_page: 50,
        search: '',
        filter_ext: '',
        continuation_token: '',
        loading: false
    };

    var s3Cache = {};
    var searchDebounceTimer = null;
    var ajaxUrl = '';
    var sesskey = '';
    var currentPage = '';

    // String cache for translations.
    var strings = {};

    /**
     * Initialize the module.
     *
     * @param {Object} config
     */
    function init(config) {
        ajaxUrl = config.ajaxurl;
        sesskey = config.sesskey;
        currentPage = config.page;

        // Load required strings.
        loadStrings().then(function() {
            initAll();
        });
    }

    /**
     * Load translated strings.
     *
     * @return {Promise}
     */
    function loadStrings() {
        var keys = [
            'confirm_delete_backup', 'confirm_run_backup', 'confirm_upload_s3',
            'confirm_delete_s3', 'confirm_delete_folder', 'backup_started', 'backup_ok',
            'backup_error', 'upload_s3_started', 'upload_s3_ok', 'upload_s3_error',
            'folder_created', 'folder_create_error', 'object_deleted', 'object_delete_error',
            'settings_saved', 'please_wait', 'loading', 'test_email_sent', 'test_email_error',
            'clear', 'pluginname'
        ];
        return Str.get_strings(keys.map(function(k) {
            return {key: k, component: 'local_mysqlbackuppro'};
        })).then(function(results) {
            keys.forEach(function(k, i) {
                strings[k] = results[i];
            });
        });
    }

    /**
     * Initialize all components based on current page.
     */
    function initAll() {
        initModal();
        initBackup();
        initUploadS3();
        initDownloads();
        initDeletes();

        if (currentPage === 'settings') {
            initSettings();
            initTestS3();
            initTestEmail();
        }

        if (currentPage === 'backups') {
            initRefresh();
        }

        if (currentPage === 's3') {
            initS3Explorer();
        }

        if (currentPage === 'logs') {
            initLogs();
        }
    }

    /* ============ AJAX HELPER ============ */

    /**
     * Make AJAX request to plugin handler.
     *
     * @param {string} action
     * @param {Object} data
     * @return {Promise}
     */
    function ajax(action, data) {
        var params = $.extend({ action: action, sesskey: sesskey }, data || {});
        return $.ajax({
            url: ajaxUrl,
            type: 'POST',
            data: params,
            dataType: 'json'
        }).then(function(response) {
            if (response && response.success) {
                return response;
            }
            return $.Deferred().reject(response && response.message ? response.message : 'Unknown error');
        }, function(jqXHR, textStatus, errorThrown) {
            var errorMsg = errorThrown || textStatus || 'Network error';
            if (jqXHR && jqXHR.responseJSON && jqXHR.responseJSON.message) {
                errorMsg = jqXHR.responseJSON.message;
            } else if (jqXHR && jqXHR.status) {
                errorMsg = 'HTTP Error: ' + jqXHR.status + ' ' + errorMsg;
            }
            return $.Deferred().reject(errorMsg);
        });
    }

    /* ============ MODAL ============ */

    function showModal(title, msg) {
        var $modal = $('#mbpro-modal').show();
        if (title) $('#mbpro-modal-title').text(title);
        if (msg) $('#mbpro-modal-msg').text(msg);
        $modal.find('.mbpro-progress-bar').removeClass('success error').addClass('active');
        return $modal;
    }

    function hideModal(success, msg) {
        var $modal = $('#mbpro-modal');
        var $bar = $modal.find('.mbpro-progress-bar').removeClass('active');
        if (success) {
            $bar.addClass('success');
        } else {
            $bar.addClass('error');
        }
        if (msg) $('#mbpro-modal-msg').text(msg);
        setTimeout(function() { $modal.hide(); }, success ? 600 : 1200);
    }

    function initModal() {
        // Modal is always present.
    }

    /* ============ BACKUP ============ */

    function initBackup() {
        $(document).on('click', '#mbpro-run-backup', function(e) {
            e.preventDefault();
            if (!confirm(strings.confirm_run_backup)) return;

            showModal(strings.running_backup || 'Running Backup...', strings.backup_started);

            ajax('run_backup').done(function(res) {
                if (res.data) {
                    hideModal(true, strings.backup_ok);
                    var d = res.data;
                    var s3Msg = d.s3 ? 'S3: Yes' : (d.s3_error ? 'S3: Failed - ' + d.s3_error : 'S3: Not configured');
                    setTimeout(function() {
                        alert(strings.backup_ok + '\n\nFile: ' + d.filename + '\nSize: ' + d.file_size + '\n' + s3Msg + '\nDuration: ' + d.duration + 's');
                        if (currentPage === 'backups') {
                            refreshBackupsList();
                        } else {
                            window.location.reload();
                        }
                    }, 300);
                }
            }).fail(function(msg) {
                hideModal(false, strings.backup_error);
                alert(strings.backup_error + '\n' + msg);
            });
        });
    }

    /* ============ UPLOAD TO S3 ============ */

    function initUploadS3() {
        $(document).on('click', '.mbpro-btn-upload-s3', function(e) {
            e.preventDefault();
            var id = $(this).data('id');
            if (!confirm(strings.confirm_upload_s3)) return;

            var $btn = $(this).prop('disabled', true);
            var $row = $('tr[data-id="' + id + '"]');

            showModal('Uploading to S3...', strings.upload_s3_started);

            ajax('upload_to_s3', { id: id }).done(function(res) {
                hideModal(true, strings.upload_s3_ok);
                $row.find('.mbpro-s3-no, .mbpro-s3-none').replaceWith(
                    '<span class="mbpro-s3-badge mbpro-s3-yes"><i class="fa fa-cloud"></i> S3</span>'
                );
                $btn.fadeOut(300, function() { $(this).remove(); });
                alert(strings.upload_s3_ok + '\n\nFile uploaded to:\n' + (res.data && res.data.s3_key ? res.data.s3_key : ''));
            }).fail(function(msg) {
                hideModal(false, strings.upload_s3_error);
                alert(strings.upload_s3_error + '\n' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ DOWNLOADS ============ */

    function initDownloads() {
        $(document).on('click', '.mbpro-btn-download', function(e) {
            e.preventDefault();
            var id = $(this).data('id');
            var $btn = $(this).prop('disabled', true);

            ajax('download_backup', { id: id }).done(function(res) {
                if (res.data) {
                    var d = res.data;
                    if (d.type === 's3') {
                        window.open(d.url, '_blank');
                    } else if (d.type === 'local') {
                        var a = $('<a>').attr({ href: d.url, download: d.filename || '' }).hide().appendTo('body');
                        a[0].click();
                        a.remove();
                    }
                }
            }).fail(function(msg) {
                alert('Error: ' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ DELETES ============ */

    function initDeletes() {
        $(document).on('click', '.mbpro-btn-delete', function(e) {
            e.preventDefault();
            var id = $(this).data('id');
            if (!confirm(strings.confirm_delete_backup)) return;

            var $btn = $(this).prop('disabled', true);
            ajax('delete_backup', { id: id }).done(function() {
                $('tr[data-id="' + id + '"]').fadeOut(300, function() {
                    $(this).remove();
                    if ($('#mbpro-backups-tbody tr').length === 0) {
                        $('#mbpro-backups-tbody').html(
                            '<tr id="mbpro-no-backups"><td colspan="10" class="mbpro-empty">No backups registered.</td></tr>'
                        );
                    }
                });
            }).fail(function(msg) {
                alert('Error: ' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ SETTINGS ============ */

    function initSettings() {
        $('#mbpro-settings-form').on('submit', function(e) {
            e.preventDefault();
            var $btn = $(this).find('button[type="submit"]').prop('disabled', true);
            
            var formData = {};
            $(this).serializeArray().forEach(function(item) {
                formData[item.name] = item.value;
            });

            // Convert checkbox values properly.
            $(this).find('input[type="checkbox"]').each(function() {
                var name = $(this).attr('name');
                formData[name] = $(this).is(':checked') ? '1' : '0';
            });

            ajax('save_settings', formData).done(function() {
                alert(strings.settings_saved);
                window.location.reload();
            }).fail(function(msg) {
                alert('Error: ' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ TEST S3 ============ */

    function initTestS3() {
        $('#mbpro-test-s3').on('click', function(e) {
            e.preventDefault();
            var $btn = $(this).prop('disabled', true);
            var $res = $('#mbpro-test-result').text('Testing...').show().css('color', '#666');

            var formData = {};
            $('#mbpro-settings-form').serializeArray().forEach(function(item) {
                formData[item.name] = item.value;
            });

            ajax('test_s3', formData).done(function(res) {
                $res.text(res.message || 'OK').css('color', '#46b450');
            }).fail(function(msg) {
                $res.text(msg || 'Connection failed').css('color', '#dc3232');
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ TEST EMAIL ============ */

    function initTestEmail() {
        $('#mbpro-test-email').on('click', function(e) {
            e.preventDefault();
            var $btn = $(this).prop('disabled', true);
            var $res = $('#mbpro-email-result').text('Sending...').show().css('color', '#666');

            ajax('test_email').done(function(res) {
                $res.text(res.message || strings.test_email_sent).css('color', '#46b450');
            }).fail(function(msg) {
                $res.text(msg || strings.test_email_error).css('color', '#dc3232');
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    /* ============ REFRESH ============ */

    function initRefresh() {
        $('#mbpro-refresh-list').on('click', function(e) {
            e.preventDefault();
            var $btn = $(this).prop('disabled', true);
            $btn.find('.fa').addClass('fa-spin');
            refreshBackupsList(function() {
                $btn.prop('disabled', false);
                $btn.find('.fa').removeClass('fa-spin');
            });
        });
    }

    function refreshBackupsList(callback) {
        ajax('get_backups').done(function(res) {
            if (res.data && res.data.backups) {
                renderBackupsTable(res.data.backups);
            }
            if (typeof callback === 'function') callback();
        }).fail(function() {
            if (typeof callback === 'function') callback();
        });
    }

    function renderBackupsTable(backups) {
        var $tbody = $('#mbpro-backups-tbody');
        if (!backups || backups.length === 0) {
            $tbody.html('<tr id="mbpro-no-backups"><td colspan="10" class="mbpro-empty">No backups registered.</td></tr>');
            return;
        }

        var html = '';
        backups.forEach(function(b) {
            var tables = b.tables_list ? b.tables_list.split(', ').length : 0;
            var hasS3 = b.s3_key && b.s3_key.length > 0;
            var hasFile = b.file_path && b.file_path.length > 0;

            var statusBadge = '';
            if (b.status === 'completed') {
                statusBadge = '<span class="mbpro-badge mbpro-badge-green">OK</span>';
            } else if (b.status === 'failed') {
                statusBadge = '<span class="mbpro-badge mbpro-badge-red" title="' + escapeHtml(b.error_msg || '') + '">Failed</span>';
            } else {
                statusBadge = '<span class="mbpro-badge mbpro-badge-orange">Pending</span>';
            }

            var s3Badge = '';
            if (hasS3) {
                s3Badge = '<span class="mbpro-s3-badge mbpro-s3-yes" title="' + escapeHtml(b.s3_key) + '"><i class="fa fa-cloud"></i> S3</span>';
            } else if (hasFile) {
                s3Badge = '<span class="mbpro-s3-badge mbpro-s3-no"><i class="fa fa-hdd-o"></i> Local</span>';
            } else {
                s3Badge = '<span class="mbpro-s3-badge mbpro-s3-none">-</span>';
            }

            var actions = '';
            if (hasFile || hasS3) {
                actions += '<button class="btn btn-icon mbpro-btn-download" data-id="' + b.id + '" title="Download"><i class="fa fa-download"></i></button>';
            }
            if (!hasS3 && hasFile) {
                actions += '<button class="btn btn-icon mbpro-btn-upload-s3" data-id="' + b.id + '" title="Upload to S3"><i class="fa fa-cloud-upload"></i></button>';
            }
            actions += '<button class="btn btn-icon mbpro-btn-delete" data-id="' + b.id + '" title="Delete"><i class="fa fa-trash"></i></button>';

            html += '<tr data-id="' + b.id + '">';
            html += '<td>' + b.id + '</td>';
            html += '<td><code>' + escapeHtml(b.file_name) + '</code></td>';
            html += '<td>' + fmtBytes(parseInt(b.file_size || 0)) + '</td>';
            html += '<td>' + tables + '</td>';
            html += '<td>' + numberFormat(b.rows_count || 0) + '</td>';
            html += '<td><span class="mbpro-type mbpro-type-' + escapeHtml(b.backup_type) + '">' + escapeHtml(b.backup_type) + '</span></td>';
            html += '<td>' + statusBadge + '</td>';
            html += '<td>' + s3Badge + '</td>';
            html += '<td>' + escapeHtml(b.completed_at ? new Date(b.completed_at * 1000).toLocaleString() : new Date(b.created_at * 1000).toLocaleString()) + '</td>';
            html += '<td class="mbpro-actions">' + actions + '</td>';
            html += '</tr>';
        });

        $tbody.html(html);
    }

    /* ============ S3 EXPLORER ============ */

    function initS3Explorer() {
        if (!$('#mbpro-s3-table').length) return;

        s3Navigate({ prefix: '', page: 1, search: '', continuation_token: '' });

        $(document).on('click', '.mbpro-s3-nav-root', function(e) {
            e.preventDefault();
            s3Navigate({ prefix: '', page: 1, search: '', continuation_token: '', filter_ext: '' });
            $('#mbpro-s3-search').val('');
            $('#mbpro-s3-filter-ext').val('');
            s3UpdateSearchUI();
        });

        $(document).on('click', '.mbpro-s3-folder-link', function(e) {
            e.preventDefault();
            var prefix = $(this).data('prefix');
            s3Navigate({ prefix: prefix, page: 1, search: '', continuation_token: '' });
        });

        $(document).on('click', '.mbpro-s3-breadcrumb-link', function(e) {
            e.preventDefault();
            var prefix = $(this).data('prefix');
            s3Navigate({ prefix: prefix, page: 1, search: '', continuation_token: '' });
        });

        $('#mbpro-s3-refresh').on('click', function(e) {
            e.preventDefault();
            var $btn = $(this).prop('disabled', true);
            $btn.find('.fa').addClass('fa-spin');
            s3ClearCache();
            s3Load(s3State, function() {
                $btn.prop('disabled', false);
                $btn.find('.fa').removeClass('fa-spin');
            });
        });

        $('#mbpro-s3-search').on('input', function() {
            var q = $(this).val().trim();
            $('#mbpro-s3-search-clear').toggle(q !== '');

            clearTimeout(searchDebounceTimer);
            searchDebounceTimer = setTimeout(function() {
                s3Navigate({ prefix: s3State.prefix, page: 1, search: q, continuation_token: '' });
            }, 350);
        });

        $('#mbpro-s3-search-clear, #mbpro-s3-clear-search-link').on('click', function(e) {
            e.preventDefault();
            $('#mbpro-s3-search').val('');
            $('#mbpro-s3-search-clear').hide();
            s3Navigate({ prefix: s3State.prefix, page: 1, search: '', continuation_token: '' });
        });

        $('#mbpro-s3-filter-ext').on('change', function() {
            s3Navigate({ prefix: s3State.prefix, page: 1, filter_ext: $(this).val(), continuation_token: '' });
        });

        $('#mbpro-s3-per-page').on('change', function() {
            s3Navigate({ prefix: s3State.prefix, page: 1, per_page: parseInt($(this).val()), continuation_token: '' });
        });

        $('#mbpro-s3-prev-page').on('click', function(e) {
            e.preventDefault();
            if (s3State.page <= 1 || s3State.loading) return;
            s3Navigate({ page: s3State.page - 1 });
        });

        $('#mbpro-s3-next-page').on('click', function(e) {
            e.preventDefault();
            if (s3State.loading) return;
            s3Navigate({ page: s3State.page + 1, continuation_token: s3State.continuation_token });
        });

        $('#mbpro-s3-first-page').on('click', function(e) {
            e.preventDefault();
            if (s3State.page <= 1 || s3State.loading) return;
            s3Navigate({ page: 1, continuation_token: '' });
        });

        // Create folder modal.
        $('#mbpro-s3-create-folder-btn').on('click', function(e) {
            e.preventDefault();
            $('#mbpro-s3-new-folder').val('');
            $('#mbpro-s3-folder-modal').show();
            setTimeout(function() { $('#mbpro-s3-new-folder').focus(); }, 100);
        });

        $('#mbpro-s3-folder-cancel').on('click', function(e) {
            e.preventDefault();
            $('#mbpro-s3-folder-modal').hide();
        });

        $('#mbpro-s3-folder-confirm').on('click', function(e) {
            e.preventDefault();
            var folder = $('#mbpro-s3-new-folder').val().trim();
            if (!folder) {
                alert('Enter a folder name.');
                return;
            }
            var $btn = $(this).prop('disabled', true);
            ajax('s3_create_folder', { folder: folder, prefix: s3State.prefix }).done(function(res) {
                $('#mbpro-s3-folder-modal').hide();
                alert(strings.folder_created + '\n' + (res.message || ''));
                s3ClearCache();
                s3Load(s3State);
            }).fail(function(msg) {
                alert(strings.folder_create_error + '\n' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });

        // Delete S3 object.
        $(document).on('click', '.mbpro-s3-delete', function(e) {
            e.preventDefault();
            var key = $(this).data('key');
            var isFolder = key.endsWith('/');
            var msg = isFolder ? strings.confirm_delete_folder : strings.confirm_delete_s3;
            if (!confirm(msg)) return;

            var $btn = $(this).prop('disabled', true);
            ajax('s3_delete_object', { key: key }).done(function() {
                s3ClearCache();
                s3Load(s3State);
            }).fail(function(msg) {
                alert(strings.object_delete_error + '\n' + msg);
            }).always(function() {
                $btn.prop('disabled', false);
            });
        });
    }

    function s3Navigate(newState) {
        if (newState.prefix !== undefined) s3State.prefix = newState.prefix;
        if (newState.page !== undefined) s3State.page = newState.page;
        if (newState.per_page !== undefined) s3State.per_page = newState.per_page;
        if (newState.search !== undefined) s3State.search = newState.search;
        if (newState.filter_ext !== undefined) s3State.filter_ext = newState.filter_ext;
        if (newState.continuation_token !== undefined) s3State.continuation_token = newState.continuation_token;
        s3Load(s3State);
    }

    function s3Load(state, callback) {
        if (s3State.loading) return;
        s3State.loading = true;

        var $tbody = $('#mbpro-s3-tbody');
        $tbody.html('<tr><td colspan="5" class="mbpro-empty"><i class="fa fa-refresh fa-spin"></i> ' + strings.loading + '</td></tr>');

        var cacheKeyStr = state.prefix + '|' + state.page + '|' + state.search + '|' + state.filter_ext + '|' + state.per_page;
        var now = Date.now();

        if (s3Cache[cacheKeyStr] && (now - s3Cache[cacheKeyStr].ts) < 25000) {
            s3Render(s3Cache[cacheKeyStr].data);
            s3State.loading = false;
            s3UpdateSearchUI();
            if (typeof callback === 'function') callback();
            return;
        }

        ajax('s3_list_objects', {
            prefix: state.prefix,
            search: state.search,
            filter_ext: state.filter_ext,
            page: state.page,
            per_page: state.per_page,
            continuation_token: state.continuation_token
        }).done(function(res) {
            s3State.loading = false;
            if (res.data) {
                s3Cache[cacheKeyStr] = { data: res.data, ts: Date.now() };
                s3State.continuation_token = res.data.continuation_token || '';
                s3Render(res.data);
            }
            s3UpdateSearchUI();
            if (typeof callback === 'function') callback();
        }).fail(function(msg) {
            s3State.loading = false;
            $tbody.html('<tr><td colspan="5" class="mbpro-empty" style="color:#dc3232;"><i class="fa fa-warning"></i> Error: ' + escapeHtml(msg) + '</td></tr>');
            s3HidePagination();
            if (typeof callback === 'function') callback();
        });
    }

    function s3Render(data) {
        var folders = data.folders || [];
        var files = data.files || [];
        var $tbody = $('#mbpro-s3-tbody');

        if (folders.length === 0 && files.length === 0) {
            var emptyMsg = data.is_search
                ? 'No files matching your search.'
                : 'Empty folder.';
            $tbody.html('<tr><td colspan="5" class="mbpro-empty"><i class="fa fa-folder-open-o" style="font-size:40px;color:#c3c4c7;display:block;margin-bottom:10px;"></i>' + emptyMsg + '</td></tr>');
            s3HidePagination();
            s3UpdateBreadcrumb(data.prefix || '');
            return;
        }

        var html = '';

        folders.forEach(function(f) {
            html += '<tr>';
            html += '<td><i class="fa fa-folder" style="color:#ffb900;font-size:20px;"></i></td>';
            html += '<td><a href="#" class="mbpro-s3-folder-link" data-prefix="' + escapeHtml(f.prefix) + '"><strong>' + escapeHtml(f.name) + '</strong>/</a></td>';
            html += '<td>-</td>';
            html += '<td>-</td>';
            html += '<td><button class="btn btn-icon mbpro-s3-delete" data-key="' + escapeHtml(f.prefix) + '" title="Delete folder"><i class="fa fa-trash"></i></button></td>';
            html += '</tr>';
        });

        files.forEach(function(f) {
            var ext = (f.name.lastIndexOf('.') > -1) ? f.name.substring(f.name.lastIndexOf('.')).toLowerCase() : '';
            var iconClass = 'fa-file-o';
            var iconColor = '#2271b1';

            if (['.sql', '.gz', '.zip', '.tar'].indexOf(ext) !== -1) {
                iconClass = 'fa-file-archive-o';
                iconColor = '#7c3aed';
            } else if (['.jpg', '.jpeg', '.png', '.gif', '.webp'].indexOf(ext) !== -1) {
                iconClass = 'fa-file-image-o';
                iconColor = '#d63638';
            } else if (ext === '.log' || ext === '.txt') {
                iconClass = 'fa-file-text-o';
                iconColor = '#646970';
            }

            html += '<tr>';
            html += '<td><i class="fa ' + iconClass + '" style="color:' + iconColor + ';font-size:20px;"></i></td>';
            html += '<td><code title="' + escapeHtml(f.key) + '">' + escapeHtml(f.name) + '</code></td>';
            html += '<td>' + fmtBytes(f.size) + '</td>';
            html += '<td>' + fmtDate(f.modified) + '</td>';
            html += '<td><button class="btn btn-icon mbpro-s3-delete" data-key="' + escapeHtml(f.key) + '" title="Delete file"><i class="fa fa-trash"></i></button></td>';
            html += '</tr>';
        });

        $tbody.html(html);
        s3UpdateBreadcrumb(data.prefix || '');
        s3UpdatePagination(data);
    }

    function s3UpdateBreadcrumb(prefix) {
        var $path = $('#mbpro-s3-breadcrumb-path');
        if (!prefix) {
            $path.html('');
            return;
        }
        var parts = prefix.replace(/\/$/, '').split('/');
        var accumulated = '';
        var html = '';
        parts.forEach(function(part, index) {
            accumulated += part + '/';
            var isLast = index === parts.length - 1;
            if (isLast) {
                html += ' <span class="mbpro-s3-breadcrumb-sep">/</span> <strong>' + escapeHtml(part) + '</strong>';
            } else {
                html += ' <span class="mbpro-s3-breadcrumb-sep">/</span> <a href="#" class="mbpro-s3-breadcrumb-link" data-prefix="' + escapeHtml(accumulated) + '">' + escapeHtml(part) + '</a>';
            }
        });
        $path.html(html);
    }

    function s3UpdatePagination(data) {
        var $pagination = $('#mbpro-s3-pagination');
        var page = data.page || 1;
        var hasNext = data.has_next || false;
        var hasPrev = data.has_prev || page > 1;

        if (data.is_search) {
            var totalPages = data.total_pages || 1;
            $('#mbpro-s3-page-info').text('Page ' + page + ' of ' + totalPages + ' (' + numberFormat(data.total_items || 0) + ' results)');
            $('#mbpro-s3-current-page').text(page + '/' + totalPages);
            $pagination.show();
            $('#mbpro-s3-prev-page').prop('disabled', page <= 1);
            $('#mbpro-s3-next-page').prop('disabled', page >= totalPages);
            $('#mbpro-s3-first-page').prop('disabled', page <= 1);
            return;
        }

        if (!hasNext && !hasPrev) {
            s3HidePagination();
            return;
        }

        $('#mbpro-s3-page-info').text('Page ' + page + (data.total_items > 0 ? ' (' + numberFormat(data.total_items) + ' items' + (hasNext ? '+' : '') + ')' : ''));
        $('#mbpro-s3-current-page').text(page);
        $pagination.show();
        $('#mbpro-s3-prev-page').prop('disabled', !hasPrev);
        $('#mbpro-s3-next-page').prop('disabled', !hasNext);
        $('#mbpro-s3-first-page').prop('disabled', !hasPrev);
    }

    function s3HidePagination() {
        $('#mbpro-s3-pagination').hide();
    }

    function s3UpdateSearchUI() {
        var $resultsInfo = $('#mbpro-s3-results-info');
        var $searchBadge = $('#mbpro-s3-search-badge');

        if (s3State.search !== '') {
            $resultsInfo.show();
            $searchBadge.show();
            $('#mbpro-s3-search-term').text(s3State.search);
        } else {
            $searchBadge.hide();
            if (s3State.filter_ext !== '') {
                $resultsInfo.show();
            } else {
                $resultsInfo.hide();
            }
        }
    }

    function s3ClearCache() {
        s3Cache = {};
    }

    /* ============ LOGS ============ */

    function initLogs() {
        refreshLogs();

        $('#mbpro-refresh-logs').on('click', function() {
            refreshLogs();
        });

        $('#mbpro-clear-logs').on('click', function() {
            if (!confirm('Are you sure you want to clear all logs?')) return;
            ajax('clear_logs').done(function() {
                $('#mbpro-logs-tbody').html('<tr><td colspan="3" class="mbpro-empty">No logs available.</td></tr>');
            });
        });

        $(document).on('change', '#mbpro-log-filter', function() {
            var level = $(this).val();
            var $rows = $('#mbpro-logs-tbody tr');
            $rows.show();
            if (level === 'all') return;
            $rows.each(function() {
                if ($(this).data('level') !== level) {
                    $(this).hide();
                }
            });
        });

        // Auto refresh every 15s when visible.
        setInterval(function() {
            if ($('#mbpro-logs-tbody').is(':visible')) {
                refreshLogs();
            }
        }, 15000);
    }

    function refreshLogs() {
        ajax('get_logs').done(function(res) {
            if (res.data && res.data.logs) {
                renderLogsTable(res.data.logs);
            }
        });
    }

    function renderLogsTable(logs) {
        var $tbody = $('#mbpro-logs-tbody');
        if (!logs || logs.length === 0) {
            $tbody.html('<tr><td colspan="3" class="mbpro-empty">No logs available.</td></tr>');
            return;
        }
        var html = '';
        logs.forEach(function(log) {
            var levelClass = 'mbpro-log-' + (log.level || 'info').toLowerCase();
            html += '<tr data-level="' + escapeHtml(log.level) + '">';
            html += '<td>' + escapeHtml(log.date) + '</td>';
            html += '<td><span class="mbpro-log-badge ' + levelClass + '">' + escapeHtml(log.level) + '</span></td>';
            html += '<td>' + escapeHtml(log.message) + '</td>';
            html += '</tr>';
        });
        $tbody.html(html);
    }

    /* ============ UTILITIES ============ */

    function fmtBytes(bytes) {
        if (bytes <= 0) return '-';
        var units = ['B', 'KB', 'MB', 'GB', 'TB'];
        var pow = Math.floor(Math.log(bytes) / Math.log(1024));
        pow = Math.min(pow, units.length - 1);
        return (bytes / Math.pow(1024, pow)).toFixed(2) + ' ' + units[pow];
    }

    function fmtDate(dateStr) {
        if (!dateStr || dateStr === '-') return '-';
        try {
            var d = new Date(dateStr);
            if (isNaN(d.getTime())) return dateStr;
            return d.toLocaleString('en-GB', {
                year: 'numeric', month: '2-digit', day: '2-digit',
                hour: '2-digit', minute: '2-digit'
            });
        } catch (e) {
            return dateStr;
        }
    }

    function escapeHtml(text) {
        if (!text) return '';
        var div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    function numberFormat(n) {
        return parseInt(n || 0).toLocaleString();
    }

    return { init: init };
});
